def _handle_bump(args):
    """Handle the bump subcommand.

    :param args: The parsed arguments
    :type args: :class:`argparse.Namespace`
    :return: bumped version string
    :rtype: str
    """
    if not args.bump:
        # No sub-subcommand provided; print help and exit successfully
        from semver import createparser
        parser = createparser()
        for p in parser._subparsers._actions:
            if hasattr(p, '_parser_class'):
                for name, subparser in p.choices.items():
                    if name == "bump":
                        subparser.print_help()
                        return None
        return None
    maptable = {'major': 'bump_major',
                'minor': 'bump_minor',
                'patch': 'bump_patch',
                'prerelease': 'bump_prerelease',
                'build': 'bump_build',
                }
    ver = parse_version_info(args.version)
    # get the respective method and call it
    func = getattr(ver, maptable[args.bump])
    return str(func())
